/**
 * V6 strategy registry. A strategy is pure data plus a pure signals(ctx) function.
 *
 * Research agents do not edit this file. Keep candidates in scripts/v6/research/ and
 * build them with defineStrategy; the coordinator merges winners here.
 *
 * What signals(ctx) gets:
 *   ctx.t         decision time: the close of the last bar
 *   ctx.barT      open time of that last closed bar (the `t` on the bar itself)
 *   ctx.bars      Map<symbol, Bar[]>, real arrays holding closed bars only. The future
 *                 is not hidden from you: it is simply not in them.
 *   ctx.ind(symbol, name, args, lag)   indicator as of the last closed bar. Use this
 *                 rather than looping over bars, it is computed once per series.
 *   ctx.universe  symbols eligible now: in the universe, warmed up, with a bar at barT
 *   ctx.params, ctx.positions, ctx.regime
 *
 * What it returns: Signal[] as in the contract. stopDistancePct is a FRACTION
 * (0.10 = 10%), the unit v6Risk uses. side 'flat' closes a position this strategy
 * holds; saying nothing about a symbol means no opinion, so the position stays open.
 */
import {
  INDICATORS, atr, donchianHigh, donchianLow, ema, realisedVol, roc, sma,
} from './v6Core.js';

export { INDICATORS, atr, donchianHigh, donchianLow, ema, realisedVol, roc, sma };

/**
 * Exit overrides that leave a position only on its hard stop or a flat signal.
 * For benchmarks and fixed reference rules: no trail, no time stop, no regime exit.
 */
export const SIGNAL_ONLY_EXITS = Object.freeze({
  breakEven: { enabled: false },
  trail: { enabled: false },
  spikeGuard: { enabled: false },
  timeStop: { enabled: false },
  regimeExit: { enabled: false },
  signalExit: { enabled: true, onFlat: true, onOpposite: true },
  partials: [],
});

/**
 * Validates and freezes a strategy. Fails loudly: a malformed strategy that silently
 * trades nothing would read as a negative research result.
 * Optional beyond the contract fields: perp (true = perp costs and funding),
 * exitOverrides (see v6Exits EXIT_PROFILES), slowAllocator (D4 counts position-changes).
 */
export function defineStrategy(s) {
  for (const key of ['id', 'name', 'timeframe', 'universe']) {
    if (!s?.[key]) throw new Error(`Strategy is missing ${key}`);
  }
  if (typeof s.signals !== 'function') throw new Error(`Strategy ${s.id} has no signals(ctx)`);
  if (s.timeframe !== '1d' && s.timeframe !== '4h') {
    throw new Error(`Strategy ${s.id}: decisions run on 1d or 4h only (contract section 2), got ${s.timeframe}`);
  }
  if (s.universe.kind === 'fixed') {
    if (!Array.isArray(s.universe.symbols) || !s.universe.symbols.length) throw new Error(`Strategy ${s.id}: fixed universe has no symbols`);
  } else if (s.universe.kind !== 'top' || !(s.universe.n > 0)) {
    throw new Error(`Strategy ${s.id}: universe must be { kind: 'fixed', symbols } or { kind: 'top', n }`);
  }
  return Object.freeze({ version: 1, params: {}, grid: {}, warmupBars: 0, ...s });
}

/**
 * Reference: hold every universe coin from the first bar. The stop is a formality
 * (no stop = no trade) set far enough away to never fire in practice.
 * Run it with modules: { risk: fullWeightRisk({ weight: 1 / n }) }, or v6Risk will
 * refuse the wide stop. It is a benchmark, not a candidate.
 */
export function buyAndHold({ symbols = ['BTCUSDT'], timeframe = '1d', id = 'buy_and_hold' } = {}) {
  return defineStrategy({
    id, name: `Buy and hold (${symbols.length} coin${symbols.length === 1 ? '' : 's'})`, timeframe,
    universe: { kind: 'fixed', symbols }, exitOverrides: SIGNAL_ONLY_EXITS,
    signals(ctx) {
      return ctx.universe.filter((symbol) => !ctx.positions.has(symbol)).map((symbol) => ({
        strategyId: id, symbol, side: 'long', score: 0.5, stopDistancePct: 0.999,
        exitProfile: 'trend', reason: 'Buy and hold', meta: {},
      }));
    },
  });
}

/**
 * Reference: long BTC while its close is above the n-day SMA, flat otherwise.
 * It proves the harness. It is not a candidate: earlier research has already seen
 * this rule, so its results are not clean evidence.
 * @param {{ n?: number, stopPct?: number }} [params] stopPct is the hard stop as a fraction
 */
export function btcAboveSma(params = {}) {
  const p = { n: 100, stopPct: 0.20, ...params };
  const id = 'btc_above_sma';
  return defineStrategy({
    id, name: `BTC above ${p.n}d SMA`, timeframe: '1d', params: p,
    grid: { n: [50, 100, 200] },
    universe: { kind: 'fixed', symbols: ['BTCUSDT'] }, warmupBars: p.n,
    exitOverrides: SIGNAL_ONLY_EXITS,
    signals(ctx) {
      const symbol = 'BTCUSDT';
      if (!ctx.universe.includes(symbol)) return [];
      const bars = ctx.bars.get(symbol);
      const close = bars[bars.length - 1].c;
      const avg = ctx.ind(symbol, 'sma', ctx.params.n);
      const up = close > avg;
      return [{
        strategyId: id, symbol, side: up ? 'long' : 'flat', score: 0.5, stopDistancePct: ctx.params.stopPct,
        exitProfile: 'trend', reason: `BTC close ${up ? 'above' : 'at or below'} its ${ctx.params.n}-day average`, meta: { close, avg },
      }];
    },
  });
}

/** Certified strategies only. Empty is a valid outcome: the engine then holds cash. */
export const STRATEGIES = Object.freeze([]);

/** Reference rules, kept apart so nothing can trade them by accident. */
export const REFERENCE_STRATEGIES = Object.freeze({ buyAndHold, btcAboveSma });

export function getStrategy(id) {
  return STRATEGIES.find((s) => s.id === id) ?? null;
}
